<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';import CalibrationMetrics from '../components/CalibrationMetrics.vue';import PairTable from '../components/PairTable.vue';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'双探头校准底稿 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading index="05 / 复核归档" title="保留校准参数，也保留结论的边界。" note="管理员批准后保存不可变快照；后续规则变更不回改已归档结果。CSV含原始读数、Deming拟合值、差值与界限外标记；剔除重算底稿另附样本状态与剔除原因。"/><Notice :message="error"/><div class="two-col"><section><h2>偏倚复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待管理员复核'}}</small><div v-if="isAdmin()" class="actions"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准偏倚复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成校准快照</button></div></article></section><section><h2>批准底稿</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED COMPARISON</p><h3>{{r.title}}</h3><p>保留 {{r.snapshot.result.n}} 组<template v-if="r.snapshot.result.total_n">（原始 {{r.snapshot.result.total_n}} 组、剔除 {{r.snapshot.result.excluded_n||0}} 组）</template> · {{r.snapshot.result.unit}} · {{r.snapshot.reviewer}}</p><div class="actions"><button @click="download(r.id)">下载校准 CSV ↓</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">查看参数快照</button></div><CalibrationMetrics v-if="expanded===r.id" :result="r.snapshot.result"/><section v-if="expanded===r.id&&r.snapshot.result.excluded_points?.length" class="excluded-block"><h3>剔除配对与原因（{{r.snapshot.result.excluded_points.length}} 组）</h3><PairTable :rows="r.snapshot.result.excluded_points" show-reason/></section></article></section></div></template>
